/// Imports that exist only for the guest shim (`guest/src/webgpu_shim.c`).
pub trait ShimApi {
    /// Host ABI revision. The shim refuses to run against a host that reports a different major revision.
    fn wasmer_wgpu_abi_version(&self, cx: &mut Cx<'_>) -> AbiResult<i32>;
    /// Instance handle an object descends from, or 0. Events are delivered per instance.
    fn wasmer_wgpu_object_instance(&self, cx: &mut Cx<'_>, handle: u32) -> AbiResult<i32>;
    fn wasmer_wgpu_instance_request_adapter(&self, cx: &mut Cx<'_>, instance: u32, options: u32, future: u64) -> AbiResult<()>;
    fn wasmer_wgpu_adapter_request_device(&self, cx: &mut Cx<'_>, adapter: u32, descriptor: u32, future: u64, lost_future: u64) -> AbiResult<()>;
    fn wasmer_wgpu_buffer_map_async(&self, cx: &mut Cx<'_>, buffer: u32, mode: u64, offset: u32, size: u32, future: u64) -> AbiResult<()>;
    fn wasmer_wgpu_device_pop_error_scope(&self, cx: &mut Cx<'_>, device: u32, future: u64) -> AbiResult<()>;
    fn wasmer_wgpu_device_create_compute_pipeline_async(&self, cx: &mut Cx<'_>, device: u32, descriptor: u32, future: u64) -> AbiResult<()>;
    fn wasmer_wgpu_device_create_render_pipeline_async(&self, cx: &mut Cx<'_>, device: u32, descriptor: u32, future: u64) -> AbiResult<()>;
    fn wasmer_wgpu_queue_on_submitted_work_done(&self, cx: &mut Cx<'_>, queue: u32, future: u64) -> AbiResult<()>;
    fn wasmer_wgpu_shader_module_get_compilation_info(&self, cx: &mut Cx<'_>, shader_module: u32, future: u64) -> AbiResult<()>;
    /// Drives the backend once and writes ready event records. Returns bytes written, or -needed if the next record does not fit.
    fn wasmer_wgpu_poll(&self, cx: &mut Cx<'_>, buf: u32, cap: u32) -> AbiResult<i32>;
    /// Counts the event records queued so far. Read it before looking for ready events, then hand it to wasmer_wgpu_wait: an event that arrives in between (and may be collected by another guest thread) makes the wait return instead of being missed.
    fn wasmer_wgpu_epoch(&self, cx: &mut Cx<'_>) -> AbiResult<u64>;
    /// Blocks until one of the listed futures is ready, any event was queued since `epoch`, or the timeout elapses; then behaves like poll. INT32_MIN means this host cannot block.
    fn wasmer_wgpu_wait(&self, cx: &mut Cx<'_>, futures: u32, count: u32, timeout_ns: u64, epoch: u64, buf: u32, cap: u32) -> AbiResult<i32>;
    /// Lets the host make progress on outstanding work. A no-op natively; one event-loop turn in a browser.
    fn wasmer_wgpu_yield(&self, cx: &mut Cx<'_>) -> AbiResult<()>;
    /// Releases one reference. Returns 1 when that was the last one held by the guest.
    fn wasmer_wgpu_instance_release(&self, cx: &mut Cx<'_>, instance: u32) -> AbiResult<i32>;
    fn wasmer_wgpu_buffer_release(&self, cx: &mut Cx<'_>, buffer: u32) -> AbiResult<i32>;
    fn wasmer_wgpu_device_release(&self, cx: &mut Cx<'_>, device: u32) -> AbiResult<i32>;
    /// Writes { u64 offset; u64 size; u32 mode; u32 state } for the current mapping. Returns 0 for an unknown buffer.
    fn wasmer_wgpu_buffer_map_info(&self, cx: &mut Cx<'_>, buffer: u32, out: u32) -> AbiResult<i32>;
    /// Serializes adapter info. Returns the bytes required; the buffer is filled only if that fits in cap.
    fn wasmer_wgpu_adapter_get_info(&self, cx: &mut Cx<'_>, adapter: u32, buf: u32, cap: u32) -> AbiResult<i32>;
    fn wasmer_wgpu_device_get_adapter_info(&self, cx: &mut Cx<'_>, device: u32, buf: u32, cap: u32) -> AbiResult<i32>;
    fn wasmer_wgpu_adapter_get_features(&self, cx: &mut Cx<'_>, adapter: u32, buf: u32, cap: u32) -> AbiResult<i32>;
    fn wasmer_wgpu_device_get_features(&self, cx: &mut Cx<'_>, device: u32, buf: u32, cap: u32) -> AbiResult<i32>;
    fn wasmer_wgpu_instance_get_wgsl_language_features(&self, cx: &mut Cx<'_>, instance: u32, buf: u32, cap: u32) -> AbiResult<i32>;
    /// Serializes { u64 usages; u32 formats; u32 presentModes; u32 alphaModes; u32 pad } followed by the three u32 arrays. Negative on error.
    fn wasmer_wgpu_surface_get_capabilities(&self, cx: &mut Cx<'_>, surface: u32, adapter: u32, buf: u32, cap: u32) -> AbiResult<i32>;
}

/// Everything a backend implements for the guest.
pub trait Api:
    GlobalApi
    + AdapterApi
    + BindGroupApi
    + BindGroupLayoutApi
    + BufferApi
    + CommandBufferApi
    + CommandEncoderApi
    + ComputePassEncoderApi
    + ComputePipelineApi
    + DeviceApi
    + ExternalTextureApi
    + InstanceApi
    + PipelineLayoutApi
    + QuerySetApi
    + QueueApi
    + RenderBundleApi
    + RenderBundleEncoderApi
    + RenderPassEncoderApi
    + RenderPipelineApi
    + SamplerApi
    + ShaderModuleApi
    + SurfaceApi
    + TextureApi
    + TextureViewApi
    + ShimApi
{
}
impl<T> Api for T where
    T: GlobalApi
        + AdapterApi
        + BindGroupApi
        + BindGroupLayoutApi
        + BufferApi
        + CommandBufferApi
        + CommandEncoderApi
        + ComputePassEncoderApi
        + ComputePipelineApi
        + DeviceApi
        + ExternalTextureApi
        + InstanceApi
        + PipelineLayoutApi
        + QuerySetApi
        + QueueApi
        + RenderBundleApi
        + RenderBundleEncoderApi
        + RenderPassEncoderApi
        + RenderPipelineApi
        + SamplerApi
        + ShaderModuleApi
        + SurfaceApi
        + TextureApi
        + TextureViewApi
        + ShimApi
{
}

// The native host implements all of it.
const _: fn() = || {
    fn complete<T: Api>() {}
    complete::<crate::host::Host>();
};

fn import_create_instance(mut env: FunctionEnvMut<'_, WebGpuEnv>, descriptor: u32) -> Result<u32, RuntimeError> {
    enter(&mut env, "wgpuCreateInstance", |host, cx| {
        let descriptor = cx.mem.read_opt::<InstanceDescriptor>(descriptor)?;
        Ok(host.create_instance(cx, descriptor.as_deref()))
    })
}

